import sys

lines = sys.stdin.read().split("\n")
limit = int(lines[0])
counts = {}
for line in lines[1:]:
    if not line.strip():
        continue
    ip, res = line.split()
    if res == "FAIL":
        counts[ip] = counts.get(ip, 0) + 1
suspects = [ip for ip, c in counts.items() if c > limit]
if suspects:
    print("\n".join(suspects))
else:
    print("NONE")

