#include <iostream>
#include <map>
#include <string>
#include <vector>
using namespace std;

int main() {
    int limit;
    cin >> limit;
    map<string, int> counts;
    vector<string> order;
    string ip, res;
    while (cin >> ip >> res) {
        if (res == "FAIL") {
            if (counts.find(ip) == counts.end()) order.push_back(ip);
            counts[ip]++;
        }
    }
    bool found = false;
    for (const string& s : order) {
        if (counts[s] > limit) {
            cout << s << endl;
            found = true;
        }
    }
    if (!found) cout << "NONE" << endl;
    return 0;
}

